#stage .ha-scene{ position:relative; width:100%; height:100%; }#stage .ha-sc{
  position:absolute; inset:0; opacity:0; pointer-events:none;
  display:flex; flex-direction:column; gap:14px; transition:opacity .3s ease;
}#stage .ha-sc.on{ opacity:1; }#stage .ha-world{ flex:1; min-height:0; display:flex; flex-direction:column; gap:10px; }#stage .ha-row{ width:100%; display:flex; gap:16px; flex-shrink:0; }#stage .ha-sup{
  flex:1; min-width:0; height:210px; display:flex; flex-direction:column; align-items:center;
  justify-content:center; gap:12px; padding:0 12px; border-radius:26px; border:2px solid #2C3852;
  background:linear-gradient(180deg,#212B3F,#141B2B); box-shadow:0 18px 44px rgba(0,0,0,.45);
  transition:border-color .25s ease, box-shadow .25s ease;
}#stage .ha-sup.live{ border-color:rgba(58,160,255,.7); box-shadow:0 0 40px rgba(58,160,255,.2); }#stage .ha-sup.bad{ border-color:rgba(244,74,106,.7); box-shadow:inset 0 0 50px rgba(244,74,106,.14); }#stage .ha-sup-t{ color:#fff; font-size:26px; font-weight:800; }#stage .ha-code{
  width:100%; padding:10px 8px; border-radius:12px; text-align:center; white-space:nowrap; overflow:hidden;
  background:rgba(10,15,25,.8); border:1.5px solid var(--border);
  color:var(--warn); font-family:var(--font-mono); font-size:16px; font-weight:700;
}#stage .ha-ars{ height:44px; align-items:center; }#stage .ha-ars i{
  flex:1; text-align:center; font-style:normal; line-height:1; font-size:42px;
  color:var(--border); opacity:.35; transition:color .25s ease, opacity .25s ease, text-shadow .25s ease;
}#stage .ha-ars i.live{ color:var(--accent-1); opacity:1; text-shadow:0 0 24px rgba(58,160,255,.7); }#stage .ha-ars i.bad{ color:var(--danger); opacity:1; text-shadow:0 0 24px rgba(244,74,106,.6); }#stage .ha-ars i.ok{ color:var(--success); opacity:1; text-shadow:0 0 22px rgba(63,185,80,.5); }#stage .ha-ars i.dim{ opacity:.1; }#stage .ha-ad{
  flex:1; min-width:0; height:150px; display:flex; flex-direction:column; align-items:center;
  justify-content:center; gap:6px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
  transition:border-color .25s ease, box-shadow .25s ease;
}#stage .ha-ad.slot{ background:transparent; border:2px dashed rgba(139,149,167,.35); }#stage .ha-ad.slot .ha-ad-t{ color:var(--text-dim); font-size:22px; }#stage .ha-ad.slot .ha-ad-s{ display:none; }#stage .ha-ad.live{ border-color:rgba(58,160,255,.7); box-shadow:0 0 40px rgba(58,160,255,.2); }#stage .ha-ad.ok{ border-color:rgba(63,185,80,.6); box-shadow:0 0 36px rgba(63,185,80,.14); }#stage .ha-ad.bad{ border-color:rgba(244,74,106,.7); box-shadow:0 0 40px rgba(244,74,106,.18); }#stage .ha-ad-t{ color:#fff; font-size:25px; font-weight:800; white-space:nowrap; }#stage .ha-ad-s{ color:var(--text-dim); font-size:18px; font-weight:600; }#stage .ha-res{
  height:330px; flex-shrink:0; display:flex; flex-direction:column; justify-content:center; gap:14px;
  padding:0 24px; border-radius:26px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
  transition:border-color .25s ease, box-shadow .25s ease;
