  width:140px; height:140px; border-radius:38px; display:flex; align-items:center; justify-content:center; font-size:76px;
  background:linear-gradient(160deg,#26344E,#1A2338); border:1.5px solid rgba(58,160,255,.5); box-shadow:0 0 60px rgba(58,160,255,.2);
}#stage .ha-fin-h{ color:#fff; font-size:64px; font-weight:900; line-height:1.16; letter-spacing:-1.6px; }#stage .ha-fin-h em{ font-style:normal; color:var(--accent-1); }#stage .ha-fin-row{ display:flex; gap:14px; justify-content:center; }#stage .ha-fin-p{
  padding:16px 26px; border-radius:100px; white-space:nowrap;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
  color:var(--text-primary); font-size:26px; font-weight:700;
}#stage .ha-save{
  padding:18px 30px; border-radius:20px; background:rgba(240,166,74,.1); border:1.5px solid rgba(240,166,74,.42);
  color:var(--warn); font-size:26px; font-weight:800; transition:transform .3s cubic-bezier(.22,1,.36,1), box-shadow .3s ease;
}#stage .ha-save.ping{ transform:scale(1.04); box-shadow:0 0 44px rgba(240,166,74,.24); }#stage .ha-strip{
  height:104px; flex-shrink:0; display:flex; align-items:center; gap:18px; padding:0 24px; border-radius:22px;
