var HA = window.__HA || (window.__HA = {});
// Column centres and row centres, in % of the scene.
HA.X = [16.5, 50, 83.5];
HA.Y = { sup: 12, ad: 39, res: 68 };
HA.CODE = ['"nightly": [5400, 6200]', '"total": 1370400', '"amount": 212.40, "USD"'];

HA.scene = function(id){ MSD.cls('.ha-sc', 'on', false); MSD.cls('#ha-sc-' + id, 'on', true); };

HA.strip = function(label, text, tone){
  MSD.cls('#ha-strip', 'bad', tone === 'bad');
  MSD.cls('#ha-strip', 'good', tone === 'good');
  MSD.q('#ha-strip-l').textContent = label;
  MSD.q('#ha-strip-t').textContent = text;
};

HA.sup = function(i, tone, chip, chipTone){
  ['live','bad'].forEach(function(c){ MSD.cls('#ha-sup-' + i, c, tone === c); });
  var v = MSD.q('#ha-sup-v-' + i);
  v.textContent = chip || 'JSON';
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, chipTone === c); });
};
HA.code = function(i, text){ MSD.q('#ha-code-' + i).textContent = text; };

HA.ar = function(row, i, tone){
  ['live','bad','ok','dim'].forEach(function(c){ MSD.cls('#ha-a' + row + '-' + i, c, tone === c); });
};
HA.ars = function(row, tone){ for(var i = 1; i <= 3; i++) HA.ar(row, i, tone); };

HA.ad = function(i, on, tone, chip, chipTone){
  var el = '#ha-ad-' + i;
  MSD.cls(el, 'slot', !on);
  ['live','ok','bad'].forEach(function(c){ MSD.cls(el, c, tone === c); });
  MSD.q('#ha-ad-t-' + i).textContent = on ? 'Adapter ' + 'ABC'[i - 1] : 'no adapter';
  MSD.q('#ha-ad-s-' + i).textContent = on ? 'to the one model' : '';
  var v = MSD.q('#ha-ad-v-' + i);
  v.textContent = chip || '—';
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, chipTone === c); });
};
HA.ads = function(on, tone, chip, chipTone){ for(var i = 1; i <= 3; i++) HA.ad(i, on, tone, chip, chipTone); };

// One result row: empty, gone, bad (a wrong price), dup (a duplicate) or ok.
HA.row = function(i, state, name, price){
  var el = '#ha-r-' + i;
  ['empty','gone','bad','dup','ok'].forEach(function(c){ MSD.cls(el, c, state === c); });
  MSD.q('#ha-r-n-' + i).textContent = name || '—';
  MSD.q('#ha-r-p-' + i).textContent = price || '';
};
HA.res = function(tone, timer, timerTone){
  ['ok','bad'].forEach(function(c){ MSD.cls('#ha-res', c, tone === c); });
  var t = MSD.q('#ha-timer');
  t.textContent = timer || '1.8 s';
  ['ok','bad','warn'].forEach(function(c){ t.classList.toggle(c, timerTone === c); });
};

// The three wrong rows from launch morning.
HA.wrong = function(){
  HA.row(1, 'bad', 'Sea Breeze Resort', '₹212');
  HA.row(2, 'dup', 'Sea Breeze Resort & Spa', '₹13,688');
  HA.row(3, 'dup', 'Seabreeze Resort and Spa', '₹13,70,400');
};
// The one card after the fix.
HA.fixed = function(offers, price){
  HA.row(1, 'ok', 'Sea Breeze Resort · ' + offers + ' offers', 'from ' + price);
  HA.row(2, 'gone'); HA.row(3, 'gone');
};

// Data travelling between two rows, in one column.
HA.flow = function(col, fromRow, toRow, n){
  MSD.particles('#ha-scene', { from:{ x:HA.X[col], y:HA.Y[fromRow] }, to:{ x:HA.X[col], y:HA.Y[toRow] },
    count:n || 5, duration:650, spread:18 });
};

HA.reset = function(){
  HA.scene('world');
  for(var i = 1; i <= 3; i++){ HA.sup(i, '', 'JSON', ''); HA.code(i, HA.CODE[i - 1]); HA.row(i, 'empty'); }
  HA.ars(1, ''); HA.ars(2, '');
  HA.ads(false, '', '—', '');
  HA.res('', '1.8 s', '');
};

HA.reset();
HA.strip('SEARCH', 'Goa, two nights, two adults.', '');
[1,2,3].forEach(function(i, k){
  MSD.after(400 + k * 500, function(){ HA.sup(i, 'live', 'JSON', ''); MSD.punch('#ha-sup-' + i, k + 1); MSD.sfx.pop(); });
});
MSD.after(2600, function(){ MSD.punch('#ha-code-2', 4); MSD.sfx.focus(); });
MSD.after(3000, function(){ HA.strip('THE CATCH', 'Per night. Paise. Dollars. Same room.', ''); });

